    func testMatchesReferenceEngine() {
        var compared = 0
        for (name, curve, samples) in cases {
            for (x, expected) in samples {
                XCTAssertEqual(curve(x), expected, accuracy: tolerance, "\(name) at x=\(x)")
                compared += 1
            }
        }
        XCTAssertEqual(compared, 225,
                       "every sample in the fixture must actually be compared")
    }

    /// Endpoints are pinned rather than solved. A port that lets the solver near
    /// them picks up rounding noise exactly where a loop boundary sits.
    func testEndpointsAreExact() {
        for (name, curve, _) in cases {
            XCTAssertEqual(curve(0), 0, "\(name) at 0")
            XCTAssertEqual(curve(1), 1, "\(name) at 1")
            XCTAssertEqual(curve(-0.5), 0, "\(name) below range")
            XCTAssertEqual(curve(1.5), 1, "\(name) above range")
        }
    }

    /// Every curve rises and never goes backwards. A solver that has lost its
    /// bracket still produces something that looks plausible plotted coarsely.
    func testMonotonic() {
        for (name, curve, _) in cases {
            var previous = -1.0
            for i in 0...200 {
                let value = curve(Double(i) / 200.0)
                XCTAssertGreaterThanOrEqual(value, previous, "\(name) went backwards at step \(i)")
                previous = value
            }
        }
    }
